INSERT INTO words (word, def, example, pronunciation_url) VALUES
('aberrant', 'Departing from an accepted standard or norm; deviating from what is normal or expected.', 'The scientist noted aberrant behavior in the test subjects after administering the new compound.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/aberra01.mp3'),
('abeyance', 'A state of temporary suspension or inactivity.', 'The project was held in abeyance until the new funding was approved.', 'https://api.dictionaryapi.dev/media/pronunciations/en/abeyance.mp3'),
('acerbic', 'Sharp and forthright in manner or speech; harsh or severe.', 'Her acerbic wit made her a feared critic in literary circles.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/acerbi01.mp3'),
('abscond', 'To leave hurriedly and secretly, typically to avoid detection or consequences.', 'The treasurer absconded with the company funds before anyone noticed the discrepancy.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/abscon01.mp3'),
('adamant', 'Refusing to be persuaded or to change one''s mind; unshakeable.', 'She was adamant that she had seen the suspect near the scene of the crime.', 'https://api.dictionaryapi.dev/media/pronunciations/en/adamant-us.mp3'),
('acrimony', 'Bitterness or ill feeling, especially in speech or manner.', 'The divorce proceedings were marked by such acrimony that the children were deeply affected.', 'https://api.dictionaryapi.dev/media/pronunciations/en/acrimony-us.mp3'),
('adventitious', 'Coming from an external source; not inherent or innate.', 'The plant developed adventitious roots along its stem after being exposed to moisture.', 'https://api.dictionaryapi.dev/media/pronunciations/en/adventitious.mp3'),
('aesthetic', 'Concerned with beauty or the appreciation of beauty.', 'The architect had a keen aesthetic sense, favoring clean lines and natural materials.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/aesthe02.mp3'),
('aggrandize', 'To increase the power, status, or wealth of someone; to enhance or exaggerate.', 'The biography was criticized for aggrandizing its subject beyond recognition.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/aggran01.mp3'),
('affectation', 'Behavior, speech, or writing that is artificial and designed to impress.', 'His British accent was a pure affectation — he had grown up in Ohio.', 'https://api.dictionaryapi.dev/media/pronunciations/en/affectation-au.mp3'),
('alacrity', 'Brisk and cheerful readiness to do something.', 'The volunteers responded with alacrity when asked to help with the disaster relief effort.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/alacri01.mp3'),
('ambivalent', 'Having mixed feelings or contradictory ideas about something or someone.', 'She felt ambivalent about the promotion — excited for the opportunity but wary of the added pressure.', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambivalent-au.mp3'),
('adumbrate', 'To report or represent in outline; to foreshadow or indicate vaguely.', 'The opening chapter adumbrates the themes that will dominate the rest of the novel.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/adumbr02.mp3'),
('anachronism', 'A thing belonging or appropriate to a period other than that in which it exists.', 'The knight''s armor was an anachronism in the otherwise modern-day setting of the film.', 'https://api.dictionaryapi.dev/media/pronunciations/en/anachronism-au.mp3'),
('amalgamate', 'To combine or unite to form one organization or structure.', 'The two rival companies decided to amalgamate in order to compete globally.', 'https://api.dictionaryapi.dev/media/pronunciations/en/amalgamate-au.mp3'),
('ameliorate', 'To make something bad or unsatisfactory better; to improve.', 'Several policy changes were introduced to ameliorate the living conditions in the region.', 'https://api.dictionaryapi.dev/media/pronunciations/en/ameliorate-au.mp3'),
('anodyne', 'Not likely to provoke dissent or offense; inoffensive, often to the point of being dull.', 'The politician gave an anodyne response that satisfied no one on either side of the debate.', 'https://api.dictionaryapi.dev/media/pronunciations/en/anodyne-uk.mp3'),
('anomalous', 'Deviating from what is standard, normal, or expected.', 'The anomalous data point suggested that the experiment had been compromised.', 'https://api.dictionaryapi.dev/media/pronunciations/en/anomalous-us.mp3'),
('apocryphal', 'Of doubtful authenticity, although widely circulated as being true.', 'The story of him swimming the river at midnight is almost certainly apocryphal.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/apocry02.mp3'),
('antipathy', 'A deep-seated feeling of dislike; aversion.', 'There was a long-standing antipathy between the two neighboring families.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/antipa09.mp3'),
('approbation', 'Approval or praise, especially from someone with authority.', 'The young artist beamed with pride at receiving the approbation of such an established critic.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/approb03.mp3'),
('arbitrary', 'Based on random choice or personal whim rather than any reason or system.', 'The arbitrary enforcement of the rules led to widespread resentment among the staff.', 'https://api.dictionaryapi.dev/media/pronunciations/en/arbitrary-au.mp3'),
('apposite', 'Apt in the circumstances or in relation to something; appropriate.', 'Her apposite remarks during the debate demonstrated a thorough understanding of the issue.', 'https://api.dictionaryapi.dev/media/pronunciations/en/apposite-uk.mp3'),
('arduous', 'Involving or requiring strenuous effort; difficult and tiring.', 'The arduous climb to the summit took the team nearly three days.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/arduou01.mp3'),
('arrogate', 'To take or claim something without justification; to appropriate.', 'The general arrogated to himself powers that belonged to the civilian government.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/arroga03.mp3'),
('arcane', 'Understood by few; mysterious or secret.', 'The professor delighted in the arcane details of medieval manuscript production.', 'https://api.dictionaryapi.dev/media/pronunciations/en/arcane-us.mp3'),
('asperity', 'Harshness of tone or manner; roughness of surface or climate.', 'He responded to the criticism with unexpected asperity, surprising those who knew him as mild-mannered.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/asperi01.mp3'),
('assiduous', 'Showing great care and perseverance; diligent.', 'Her assiduous preparation for the bar exam paid off with a near-perfect score.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/assidu02.mp3'),
('atavistic', 'Relating to or characterized by reversion to something ancient or ancestral.', 'The film tapped into an atavistic fear of the dark that most viewers recognized immediately.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/atavis02.mp3'),
('ascetic', 'Characterized by severe self-discipline and abstention from indulgence.', 'The monks led an ascetic life, rising before dawn and eating only one meal a day.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/asceti01.mp3'),
('attenuate', 'To reduce the force, effect, or value of something; to weaken.', 'The signal became attenuated as it traveled through the dense material.', 'https://api.dictionaryapi.dev/media/pronunciations/en/attenuate-us.mp3'),
('audacious', 'Showing a willingness to take surprisingly bold risks; recklessly daring.', 'The audacious heist involved bribing security guards at three separate buildings simultaneously.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/a/audaci01.mp3'),
('augment', 'To make something greater by adding to it; to increase or supplement.', 'She augmented her income by freelancing on weekends.', 'https://api.dictionaryapi.dev/media/pronunciations/en/augment-au.mp3'),
('auspicious', 'Conducive to success; favorable.', 'Winning the regional competition was an auspicious start to her professional career.', 'https://api.dictionaryapi.dev/media/pronunciations/en/auspicious-us.mp3'),
('avarice', 'Extreme greed for wealth or material gain.', 'His avarice eventually alienated every friend and ally he had ever made.', 'https://api.dictionaryapi.dev/media/pronunciations/en/avarice-us.mp3'),
('banal', 'So lacking in originality as to be obvious and boring; trite.', 'The speech was full of banal platitudes that left the audience unmoved.', 'https://api.dictionaryapi.dev/media/pronunciations/en/banal-uk.mp3'),
('bellicose', 'Demonstrating aggression and willingness to fight; warlike.', 'The bellicose rhetoric from both sides made diplomats fear an imminent conflict.', 'https://api.dictionaryapi.dev/media/pronunciations/en/bellicose-uk.mp3'),
('beneficent', 'Resulting in good; doing or producing good.', 'The foundation''s beneficent work transformed dozens of rural communities.', 'https://api.dictionaryapi.dev/media/pronunciations/en/beneficent-us.mp3'),
('blandish', 'To coax with flattery; to cajole.', 'He tried to blandish his way into the exclusive club by complimenting the doorman excessively.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/b/blandi01.mp3'),
('bombastic', 'High-sounding language with little meaning; inflated or pretentious.', 'The senator''s bombastic speech was long on rhetoric and short on substance.', 'https://api.dictionaryapi.dev/media/pronunciations/en/bombastic-au.mp3'),
('boorish', 'Rough and bad-mannered; coarse.', 'His boorish behavior at the dinner table embarrassed everyone present.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/b/booris01.mp3'),
('brusque', 'Abrupt or offhand in speech or manner; blunt.', 'The surgeon''s brusque manner unsettled patients who expected more warmth.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/b/brusqu01.mp3'),
('bucolic', 'Relating to the pleasant aspects of the countryside and rural life.', 'They dreamed of retiring to a bucolic cottage surrounded by rolling hills and sheep.', 'https://api.dictionaryapi.dev/media/pronunciations/en/bucolic-au.mp3'),
('capricious', 'Given to sudden and unaccountable changes of mood or behavior; unpredictable.', 'The capricious weather made it impossible to plan any outdoor events with confidence.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/c/capric05.mp3'),
('castigate', 'To reprimand someone severely; to criticize harshly.', 'The editorial castigated the council for its failure to address the housing crisis.', 'https://api.dictionaryapi.dev/media/pronunciations/en/castigate-au.mp3'),
('celerity', 'Swiftness of movement or action; speed.', 'The crisis team responded with impressive celerity, arriving on site within the hour.', 'https://api.dictionaryapi.dev/media/pronunciations/en/celerity-us.mp3'),
('censure', 'To express severe disapproval of someone or something, typically in a formal statement.', 'The board voted to censure the director for misusing company funds.', 'https://api.dictionaryapi.dev/media/pronunciations/en/censure-au.mp3'),
('chimerical', 'Hoped for but illusory or impossible to achieve; fantastical.', 'Critics dismissed the startup''s promises as chimerical and unsupported by any real plan.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/c/chimer05.mp3'),
('circumspect', 'Wary and unwilling to take risks; cautious and prudent.', 'She was circumspect in her dealings with new clients until trust was established.', 'https://api.dictionaryapi.dev/media/pronunciations/en/circumspect-au.mp3'),
('clandestine', 'Kept secret or done secretively, especially because illicit.', 'The two diplomats held a clandestine meeting to negotiate terms before the official talks.', 'https://api.dictionaryapi.dev/media/pronunciations/en/clandestine-au.mp3'),
('cogent', 'Clear, logical, and convincing; compelling.', 'The lawyer presented a cogent argument that left the jury with little room for doubt.', 'https://api.dictionaryapi.dev/media/pronunciations/en/cogent-au.mp3'),
('complacent', 'Showing smug or uncritical satisfaction with oneself or one''s achievements.', 'The team grew complacent after their early success and failed to prepare for the semifinals.', 'https://api.dictionaryapi.dev/media/pronunciations/en/complacent-us.mp3'),
('compunction', 'A feeling of guilt or moral scruple about doing something wrong.', 'He fired his assistant without a moment''s compunction, citing budget constraints.', 'https://api.dictionaryapi.dev/media/pronunciations/en/compunction-au.mp3'),
('condescend', 'To act in a way that betrays a feeling of superiority; to patronize.', 'She condescended to her colleagues in a way that made collaboration nearly impossible.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/c/condes01.mp3'),
('conflagration', 'An extensive fire that destroys a great deal; a large and destructive conflict.', 'The conflagration spread from the warehouse district to three neighboring blocks within an hour.', 'https://api.dictionaryapi.dev/media/pronunciations/en/conflagration-us.mp3'),
('convoluted', 'Extremely complex and difficult to follow; intricate.', 'The convoluted plot of the novel required readers to keep detailed notes just to follow along.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/c/convol02.mp3'),
('covetous', 'Having or showing a great desire to possess something belonging to someone else.', 'She cast a covetous eye over her neighbor''s garden every time she passed by.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/c/coveto01.mp3'),
('craven', 'Contemptibly lacking in courage; cowardly.', 'His craven refusal to speak up during the meeting cost his colleague her job.', 'https://api.dictionaryapi.dev/media/pronunciations/en/craven-uk.mp3'),
('culpable', 'Deserving blame or censure; at fault.', 'The investigation found all three managers culpable for the safety violations.', 'https://api.dictionaryapi.dev/media/pronunciations/en/culpable-us.mp3'),
('cupidity', 'Greed for money or possessions; avarice.', 'The trader''s cupidity led him to take risks that eventually destroyed the firm.', 'https://api.dictionaryapi.dev/media/pronunciations/en/cupidity-uk.mp3'),
('dauntless', 'Showing fearlessness and determination; intrepid.', 'The dauntless explorer pressed on despite harsh weather and dwindling supplies.', 'https://api.dictionaryapi.dev/media/pronunciations/en/dauntless-uk.mp3'),
('debacle', 'A sudden and ignominious failure; a complete disaster.', 'The product launch was a debacle — the website crashed and orders were lost for days.', 'https://api.dictionaryapi.dev/media/pronunciations/en/debacle-au.mp3'),
('decorum', 'Behavior in keeping with good taste and propriety; dignity.', 'The judge reminded the gallery to maintain decorum throughout the proceedings.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/decoru01.mp3'),
('deleterious', 'Causing harm or damage; injurious.', 'The long-term deleterious effects of the chemical on the environment were only discovered decades later.', 'https://api.dictionaryapi.dev/media/pronunciations/en/deleterious-au.mp3'),
('demagogue', 'A political leader who seeks support by appealing to popular desires and prejudices.', 'The historian argued that every era produces its own demagogues who exploit public anxiety.', 'https://api.dictionaryapi.dev/media/pronunciations/en/demagogue-uk.mp3'),
('denouement', 'The final part of a narrative in which strands of the plot are drawn together and resolved.', 'The denouement of the mystery revealed that the killer had been hiding in plain sight all along.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/denoue01.mp3'),
('deprecate', 'To express disapproval of; to belittle.', 'He had a habit of deprecating his own achievements, which frustrated those who admired him.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/deprec01.mp3'),
('didactic', 'Intended to teach, particularly in having moral instruction as an ulterior motive.', 'The novel felt overly didactic, as if the author were more interested in lecturing than storytelling.', 'https://api.dictionaryapi.dev/media/pronunciations/en/didactic-au.mp3'),
('diatribe', 'A forceful and bitter verbal attack against someone or something.', 'His op-ed devolved into a diatribe against the entire publishing industry.', 'https://api.dictionaryapi.dev/media/pronunciations/en/diatribe-uk.mp3'),
('derelict', 'In a very poor condition as a result of disuse and neglect; negligent.', 'The derelict warehouse on the waterfront had been abandoned for over thirty years.', 'https://api.dictionaryapi.dev/media/pronunciations/en/derelict-uk.mp3'),
('diffident', 'Modest or shy due to a lack of self-confidence.', 'The diffident student rarely raised her hand despite consistently having the right answer.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/diffid02.mp3'),
('dilatory', 'Slow to act; intended to cause delay.', 'The company''s dilatory tactics in the lawsuit frustrated the plaintiffs for years.', 'https://api.dictionaryapi.dev/media/pronunciations/en/dilatory-uk.mp3'),
('discordant', 'Disagreeing or incongruous; not in harmony.', 'The discordant notes in the second movement were intentional, reflecting the chaos of wartime.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/discor05.mp3'),
('disparate', 'Essentially different in kind; not allowing comparison.', 'The committee brought together people with disparate backgrounds and expertise.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/dispar04.mp3'),
('dispassionate', 'Not influenced by strong emotion; objective and impartial.', 'The mediator offered a dispassionate assessment of each side''s position.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/dispas02.mp3'),
('dogmatic', 'Inclined to lay down principles as undeniably true; asserting opinions in an authoritative manner.', 'His dogmatic approach to management left no room for creative input from his team.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/dogmat01.mp3'),
('dubious', 'Hesitating or doubting; of questionable value or truth.', 'She was dubious about the scheme from the outset but agreed to give it a chance.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/d/dubiou01.mp3'),
('ebullient', 'Cheerful and full of energy; exuberant.', 'His ebullient personality made him the natural choice to host the annual gala.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/ebulli04.mp3'),
('efficacious', 'Successful in producing a desired or intended result; effective.', 'The new treatment proved efficacious in clinical trials, reducing symptoms in 80% of patients.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/effica01.mp3'),
('effrontery', 'Insolent or impertinent behavior; shameless boldness.', 'She had the effrontery to ask for a raise the same week she missed three deadlines.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/effron01.mp3'),
('egregious', 'Outstandingly bad; shocking or remarkable in a negative way.', 'The report detailed the most egregious violations of human rights in the region''s history.', 'https://api.dictionaryapi.dev/media/pronunciations/en/egregious-us.mp3'),
('eloquent', 'Fluent or persuasive in speaking or writing; clearly expressed.', 'The senator delivered an eloquent speech that moved many in the chamber to tears.', 'https://api.dictionaryapi.dev/media/pronunciations/en/eloquent-uk.mp3'),
('emollient', 'Having the quality of softening or soothing the skin; tending to soften in feeling or temper.', 'The diplomat adopted an emollient tone to ease the tension between the two delegations.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/emolli01.mp3'),
('empirical', 'Based on observation or experience rather than theory or pure logic.', 'The study provided empirical evidence that the intervention was reducing crime rates.', 'https://api.dictionaryapi.dev/media/pronunciations/en/empirical-us.mp3'),
('endemic', 'Regularly found among particular people or in a certain area; native or restricted to.', 'Corruption had become so endemic that most citizens had simply accepted it as normal.', 'https://api.dictionaryapi.dev/media/pronunciations/en/endemic-au.mp3'),
('enervate', 'To weaken or drain of energy or vitality.', 'The oppressive heat enervated the workers, slowing productivity to a crawl.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/enerva01.mp3'),
('ephemeral', 'Lasting for a very short time; transitory.', 'Social media fame is often ephemeral, fading as quickly as it arrives.', 'https://api.dictionaryapi.dev/media/pronunciations/en/ephemeral-us.mp3'),
('enigmatic', 'Difficult to interpret or understand; mysterious.', 'The Mona Lisa''s enigmatic smile has captivated viewers for over five centuries.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/enigma02.mp3'),
('equivocate', 'To use ambiguous language so as to conceal the truth or avoid committing oneself.', 'When pressed on the timeline, the minister equivocated rather than give a straight answer.', 'https://api.dictionaryapi.dev/media/pronunciations/en/equivocate-us.mp3'),
('esoteric', 'Intended for or likely to be understood by only a small number of people with specialized knowledge.', 'The lecture was so esoteric that most of the audience left more confused than when they arrived.', 'https://api.dictionaryapi.dev/media/pronunciations/en/esoteric-au.mp3'),
('erudite', 'Having or showing great knowledge or learning; scholarly.', 'Her erudite commentary on the ancient texts impressed even the most seasoned academics.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/erudit02.mp3'),
('estimable', 'Worthy of great respect; admirable.', 'He was an estimable colleague whose quiet contributions were often overlooked.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/estima01.mp3'),
('eulogy', 'A speech or piece of writing that praises someone or something highly, typically at a funeral.', 'Her eulogy for her mentor was so heartfelt that there was not a dry eye in the chapel.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/eulogy01.mp3'),
('euphemism', 'A mild or indirect word or expression substituted for one considered to be too harsh or blunt.', '"Passed away" is a common euphemism for death used to soften the impact of the news.', 'https://api.dictionaryapi.dev/media/pronunciations/en/euphemism-us.mp3'),
('evanescent', 'Soon passing out of sight, memory, or existence; quickly fading or disappearing.', 'The evanescent beauty of cherry blossoms is part of what makes them so treasured in Japanese culture.', 'https://api.dictionaryapi.dev/media/pronunciations/en/evanescent-uk.mp3'),
('exacerbate', 'To make a problem, bad situation, or negative feeling worse.', 'The drought exacerbated an already serious food shortage across the region.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/exacer01.mp3'),
('excoriate', 'To criticize someone severely; to damage or remove part of the skin.', 'The review excoriated the director for what it called a cynical and lazy adaptation.', 'https://api.dictionaryapi.dev/media/pronunciations/en/excoriate-uk.mp3'),
('exigent', 'Pressing and demanding; requiring immediate attention.', 'The exigent circumstances justified the decision to bypass the usual approval process.', 'https://api.dictionaryapi.dev/media/pronunciations/en/exigent-uk.mp3'),
('expedient', 'Convenient and practical, though possibly improper or immoral; a means to an end.', 'Telling a small lie seemed expedient at the time, but it only complicated matters later.', 'https://api.dictionaryapi.dev/media/pronunciations/en/expedient-us.mp3'),
('exonerate', 'To officially absolve someone from blame or a criminal charge.', 'New DNA evidence exonerated the man who had spent sixteen years in prison.', 'https://api.dictionaryapi.dev/media/pronunciations/en/exonerate-au.mp3'),
('expunge', 'To obliterate or remove completely; to erase.', 'He petitioned the court to expunge the minor offense from his criminal record.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/expung01.mp3'),
('extraneous', 'Irrelevant or unrelated to the subject being dealt with; not essential.', 'The editor removed several extraneous paragraphs that distracted from the main argument.', 'https://api.dictionaryapi.dev/media/pronunciations/en/extraneous-au.mp3'),
('extant', 'Still in existence; surviving.', 'Only three extant copies of the original manuscript are known to exist.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/e/extant01.mp3'),
('fallacious', 'Based on a mistaken belief; containing a fallacy.', 'The argument rested on the fallacious assumption that correlation implies causation.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/fallac01.mp3'),
('fatuous', 'Silly and pointless; devoid of intelligence.', 'The interviewer grew visibly frustrated with the candidate''s fatuous answers.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/fatuou01.mp3'),
('felicitous', 'Well chosen or suited to the circumstances; pleasing and fortunate.', 'The speaker made a felicitous choice of words that perfectly captured the mood of the occasion.', 'https://api.dictionaryapi.dev/media/pronunciations/en/felicitous-uk.mp3'),
('feckless', 'Lacking initiative or strength of character; irresponsible.', 'The feckless manager delegated every decision and avoided all accountability.', 'https://api.dictionaryapi.dev/media/pronunciations/en/feckless-au.mp3'),
('fervent', 'Having or displaying a passionate intensity; ardent.', 'She was a fervent advocate for prison reform throughout her entire career.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/ferven02.mp3'),
('filibuster', 'A prolonged speech that obstructs progress in a legislative assembly; an action that obstructs.', 'The senator staged a twelve-hour filibuster to delay the vote on the controversial bill.', 'https://api.dictionaryapi.dev/media/pronunciations/en/filibuster-au.mp3'),
('flagrant', 'Conspicuously or obviously offensive; blatant.', 'The flagrant disregard for safety regulations resulted in three serious injuries.', 'https://api.dictionaryapi.dev/media/pronunciations/en/flagrant-au.mp3'),
('florid', 'Having a red or flushed complexion; elaborately intricate and showy in style.', 'His florid writing style, full of ornate metaphors, had gone out of fashion decades ago.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/florid01.mp3'),
('foment', 'To instigate or stir up an undesirable or violent sentiment or course of action.', 'The pamphlets were designed to foment unrest among the working class.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/foment02.mp3'),
('fortuitous', 'Happening by chance rather than intention; lucky or fortunate.', 'Their meeting at the conference turned out to be fortuitous — they launched a company together six months later.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/fortui01.mp3'),
('fractious', 'Irritable and quarrelsome; difficult to control.', 'The fractious coalition government collapsed after only eight months in power.', 'https://api.dictionaryapi.dev/media/pronunciations/en/fractious-uk.mp3'),
('furtive', 'Attempting to avoid notice or attention, typically because of guilt or a belief that discovery would lead to trouble.', 'He cast a furtive glance over his shoulder before slipping the document into his bag.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/f/furtiv01.mp3'),
('garrulous', 'Excessively talkative, especially on trivial matters.', 'The garrulous passenger made the six-hour flight feel twice as long.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/g/garrul02.mp3'),
('grandiloquent', 'Pompous or extravagant in language, style, or manner.', 'The CEO''s grandiloquent vision statement was mocked internally for its lack of any concrete goals.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/g/grandi02.mp3'),
('gratuitous', 'Uncalled for; lacking good reason; unwarranted.', 'Critics argued that the violence in the film was gratuitous and added nothing to the story.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/g/gratui01.mp3'),
('gregarious', 'Fond of company; sociable.', 'Her gregarious nature made her instantly popular at every new school she attended.', 'https://api.dictionaryapi.dev/media/pronunciations/en/gregarious-au.mp3'),
('guile', 'Sly or cunning intelligence; deceitfulness.', 'He navigated the corporate politics with remarkable guile, never revealing his true intentions.', 'https://api.dictionaryapi.dev/media/pronunciations/en/guile-uk.mp3'),
('hackneyed', 'Lacking significance through having been overused; unoriginal and trite.', 'The screenplay was full of hackneyed dialogue that felt lifted from a dozen other films.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/h/hackne02.mp3'),
('harangue', 'A lengthy and aggressive speech; to lecture at length in an aggressive manner.', 'The coach harangued the team for twenty minutes after their dismal first-half performance.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/h/harang01.mp3'),
('hubris', 'Excessive pride or self-confidence, often leading to downfall.', 'His hubris in assuming the deal was already done led him to stop negotiating too early.', 'https://api.dictionaryapi.dev/media/pronunciations/en/hubris-au.mp3'),
('hegemony', 'Leadership or dominance, especially of one country or social group over others.', 'The novel explores the cultural hegemony of the colonial power over the indigenous population.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/h/hegemo02.mp3'),
('ignominious', 'Deserving or causing public disgrace or shame; humiliating.', 'The team suffered an ignominious defeat, losing by thirty points to their fiercest rivals.', 'https://api.dictionaryapi.dev/media/pronunciations/en/ignominious-us.mp3'),
('iconoclast', 'A person who attacks cherished beliefs or institutions; one who destroys religious images.', 'She was an iconoclast in the field, challenging assumptions that had gone unquestioned for decades.', 'https://api.dictionaryapi.dev/media/pronunciations/en/iconoclast-au.mp3'),
('immutable', 'Unchanging over time or unable to be changed; permanent.', 'The laws of thermodynamics are considered immutable by the scientific community.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/immuta01.mp3'),
('impassive', 'Not feeling or showing emotion; calm.', 'The defendant remained impassive throughout the reading of the verdict.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/impass11.mp3'),
('imperious', 'Assuming power or authority without justification; arrogant and domineering.', 'Her imperious manner alienated colleagues who might otherwise have supported her ideas.', 'https://api.dictionaryapi.dev/media/pronunciations/en/imperious-au.mp3'),
('imperturbable', 'Unable to be upset or excited; calm and composed.', 'The surgeon''s imperturbable composure in the operating room inspired confidence in her team.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/impert04.mp3'),
('impetuous', 'Acting or done quickly and without thought or care; impulsive.', 'His impetuous decision to quit without another job lined up surprised everyone who knew him.', 'https://api.dictionaryapi.dev/media/pronunciations/en/impetuous-au.mp3'),
('impugn', 'To dispute the truth, validity, or honesty of something; to call into question.', 'Defense counsel moved to impugn the credibility of the prosecution''s key witness.', 'https://api.dictionaryapi.dev/media/pronunciations/en/impugn-us.mp3'),
('inchoate', 'Just begun and not fully formed or developed; undeveloped.', 'The proposal was still inchoate, more a collection of vague ideas than a workable plan.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/inchoa01.mp3'),
('incorrigible', 'Not able to be corrected, improved, or reformed.', 'He was an incorrigible optimist, finding a silver lining even in the worst situations.', 'https://api.dictionaryapi.dev/media/pronunciations/en/incorrigible-au.mp3'),
('indolent', 'Wanting to avoid activity or exertion; lazy.', 'The indolent student coasted through the first semester on natural ability alone.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/indole05.mp3'),
('ineluctable', 'Unable to be resisted or avoided; inescapable.', 'The ineluctable march of time spares no one, no matter how wealthy or powerful.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/ineluc01.mp3'),
('inexorable', 'Impossible to stop or prevent; continuing without any possibility of being stopped.', 'The inexorable rise of automation is reshaping entire industries.', 'https://api.dictionaryapi.dev/media/pronunciations/en/inexorable-au.mp3'),
('inimical', 'Tending to obstruct or harm; hostile or unfriendly.', 'The new regulations were inimical to small business growth and widely criticized.', 'https://api.dictionaryapi.dev/media/pronunciations/en/inimical-us.mp3'),
('iniquitous', 'Grossly unfair and morally wrong; wicked.', 'The campaigners argued that the tax system was fundamentally iniquitous.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/iniqui01.mp3'),
('insidious', 'Proceeding in a gradual, subtle way but with harmful effects.', 'The most insidious forms of bias are those we are least aware of in ourselves.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/insidi01.mp3'),
('intractable', 'Hard to control or deal with; difficult to manage.', 'The conflict had become so intractable that international mediators had largely given up hope.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/intrac11.mp3'),
('inveterate', 'Having a particular habit, activity, or interest that is deeply established; habitual.', 'He was an inveterate traveler, rarely spending more than three months in any one place.', 'https://api.dictionaryapi.dev/media/pronunciations/en/inveterate-uk.mp3'),
('irascible', 'Having or showing a tendency to be easily angered; irritable.', 'The irascible professor was feared by students but respected for his exacting standards.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/i/irasci01.mp3'),
('laconic', 'Using very few words; brief and concise.', 'His laconic reply — a single raised eyebrow — communicated everything that needed to be said.', 'https://api.dictionaryapi.dev/media/pronunciations/en/laconic-au.mp3'),
('lassitude', 'Physical or mental weariness; lack of energy.', 'A deep lassitude settled over the team after months of overwork and missed deadlines.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/l/lassit01.mp3'),
('lethologica', 'The inability to remember the right word; the tip-of-the-tongue phenomenon where a word is temporarily inaccessible.', 'He experienced a moment of lethologica mid-sentence, grasping for the word that had just been on the tip of his tongue.', 'ssl.gstatic.com/dictionary/static/sounds/20250617/lethologica--_us_1.mp3'),
('loquacious', 'Tending to talk a great deal; talkative.', 'The loquacious host filled every silence with anecdotes, leaving guests exhausted by evening''s end.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/l/loquac01.mp3'),
('lugubrious', 'Looking or sounding sad and dismal; mournful.', 'The actor specialized in lugubrious roles, his drooping features perfectly suited to tragedy.', 'https://api.dictionaryapi.dev/media/pronunciations/en/lugubrious-us.mp3'),
('magnanimous', 'Generous or forgiving, especially toward a rival or less powerful person.', 'In victory, she was magnanimous, praising her opponent''s campaign and wishing him well.', 'https://api.dictionaryapi.dev/media/pronunciations/en/magnanimous-au.mp3'),
('malapropism', 'The mistaken use of a word in place of a similar-sounding one, often with unintentionally comic effect.', 'Saying "for all intensive purposes" instead of "for all intents and purposes" is a common malapropism.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/m/malapr03.mp3'),
('malleable', 'Easily influenced; pliable; capable of being shaped or bent.', 'Gold is one of the most malleable metals, which is why it has been worked by jewelers for millennia.', 'https://api.dictionaryapi.dev/media/pronunciations/en/malleable-us.mp3'),
('mendacious', 'Not telling the truth; lying.', 'The report described the official''s account as mendacious and deliberately misleading.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/m/mendac01.mp3'),
('mercurial', 'Subject to sudden or unpredictable changes of mood or mind.', 'Working with the mercurial director was exciting but exhausting — no one ever knew what to expect.', 'https://api.dictionaryapi.dev/media/pronunciations/en/mercurial-uk.mp3'),
('meticulous', 'Showing great attention to detail or being very careful and precise.', 'The restorer was meticulous in her work, spending weeks on a single square inch of the painting.', 'https://api.dictionaryapi.dev/media/pronunciations/en/meticulous-uk.mp3'),
('mnemonic', 'Aiding or designed to aid the memory; a device such as a pattern or rhyme used to aid memorization.', '"Every Good Boy Does Fine" is a classic mnemonic for remembering the lines of the treble clef.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/m/mnemon01.mp3'),
('mollify', 'To appease the anger or anxiety of someone; to soothe.', 'The manager tried to mollify the angry customer with a full refund and an apology.', 'https://api.dictionaryapi.dev/media/pronunciations/en/mollify-us.mp3'),
('morose', 'Sullen and ill-tempered; gloomy.', 'He became increasingly morose as the evening wore on and the news got worse.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/m/morose01.mp3'),
('munificent', 'More generous than is usual or expected; lavishly generous.', 'The munificent donor funded an entire new wing of the hospital anonymously.', 'https://api.dictionaryapi.dev/media/pronunciations/en/munificent-uk.mp3'),
('myopic', 'Lacking imagination, foresight, or intellectual insight; short-sighted.', 'Critics accused the government of a myopic approach to climate policy.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/m/myopia03.mp3'),
('nefarious', 'Wicked or criminal; flagrantly villainous.', 'The investigation uncovered a nefarious scheme to defraud elderly investors.', 'https://api.dictionaryapi.dev/media/pronunciations/en/nefarious-au.mp3'),
('neologism', 'A newly coined word or expression, or the coining of new words.', '"Selfie" is a neologism that entered mainstream usage in the early 2010s.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/n/neolog01.mp3'),
('nepotism', 'The practice of favoring relatives or close friends in professional appointments.', 'The CEO was accused of nepotism after appointing three family members to senior positions.', 'https://api.dictionaryapi.dev/media/pronunciations/en/nepotism-au.mp3'),
('nihilism', 'The rejection of all religious and moral principles, in the belief that life is meaningless.', 'The philosophy student flirted with nihilism before ultimately finding meaning in community.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/n/nihili02.mp3'),
('obdurate', 'Stubbornly refusing to change one''s opinion or course of action; hardened.', 'Despite mounting evidence, the committee remained obdurate in its original position.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/obdura02.mp3'),
('obsequious', 'Obedient or attentive to an excessive or servile degree; fawning.', 'The obsequious assistant laughed at every joke the boss made, no matter how weak.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/obsequ01.mp3'),
('obstreperous', 'Noisy and difficult to control; unruly.', 'The obstreperous crowd made it impossible for the speaker to be heard.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/obstre01.mp3'),
('obtuse', 'Annoyingly insensitive or slow to understand; not sharp or pointed.', 'She suspected he was being deliberately obtuse rather than genuinely failing to grasp the issue.', 'https://api.dictionaryapi.dev/media/pronunciations/en/obtuse-au.mp3'),
('odious', 'Extremely unpleasant; repulsive; deserving hatred.', 'The practice was described in the report as odious and in violation of international law.', 'https://api.dictionaryapi.dev/media/pronunciations/en/odious-au.mp3'),
('officious', 'Asserting authority or interfering in an annoyingly overbearing way.', 'The officious clerk insisted on checking every document twice despite the long queue behind.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/offici12.mp3'),
('onerous', 'Involving a great deal of effort, trouble, or difficulty; burdensome.', 'The onerous reporting requirements drove many small nonprofits to dissolve.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/onerou02.mp3'),
('opaque', 'Not transparent; hard to understand; not clearly expressed or easily understood.', 'The contract was written in opaque legal language that few could interpret without a lawyer.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/opaque01.mp3'),
('opprobrium', 'Harsh criticism or censure; public disgrace.', 'The decision drew widespread opprobrium from advocacy groups across the political spectrum.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/opprob02.mp3'),
('ostensible', 'Stated or appearing to be true, but not necessarily so; apparent.', 'His ostensible reason for the visit was business, but everyone suspected an ulterior motive.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/ostens01.mp3'),
('ostentatious', 'Characterized by a showy display intended to impress; pretentious.', 'The ostentatious mansion was designed to signal wealth rather than provide comfort.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/ostent02.mp3'),
('overwrought', 'In a state of excessive nervousness, excitement, or agitation; too elaborate or complicated.', 'The prose was so overwrought that readers struggled to find the actual story beneath it.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/o/overwr05.mp3'),
('pariah', 'An outcast; a person rejected by a social group.', 'After the scandal, he became a pariah in the industry and found it impossible to get work.', 'https://api.dictionaryapi.dev/media/pronunciations/en/pariah-au.mp3'),
('parsimonious', 'Unwilling to spend money or use resources; extremely frugal or miserly.', 'The parsimonious founder refused to buy new office chairs even as the company grew profitable.', 'https://api.dictionaryapi.dev/media/pronunciations/en/parsimonious-uk.mp3'),
('pedantic', 'Overly concerned with minor details or rules; showing off learning in a tiresome way.', 'His pedantic insistence on correcting every grammatical slip made him tedious company.', 'https://api.dictionaryapi.dev/media/pronunciations/en/pedantic-au.mp3'),
('perfidious', 'Deceitful and untrustworthy; guilty of betrayal.', 'The general was remembered in history as a perfidious traitor who sold plans to the enemy.', 'https://api.dictionaryapi.dev/media/pronunciations/en/perfidious-uk.mp3'),
('panacea', 'A solution or remedy for all difficulties or diseases; a cure-all.', 'Technology is often presented as a panacea for social problems, but the reality is more complex.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/panace01.mp3'),
('perfunctory', 'Carried out with minimal effort or reflection; routine and superficial.', 'The safety inspection was so perfunctory that the inspector missed several obvious hazards.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/perfun01.mp3'),
('perspicacious', 'Having a ready insight into things; shrewd and discerning.', 'A perspicacious investor, she had moved her assets out of the sector months before the crash.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/perspi01.mp3'),
('pertinacious', 'Holding firmly to an opinion or a course of action; stubbornly persistent.', 'The pertinacious journalist refused to drop the story despite pressure from editors.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/pertin01.mp3'),
('petulant', 'Childishly sulky or bad-tempered; irritable.', 'The actor stormed off set in a petulant rage after the director asked for one more take.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/petula03.mp3'),
('pious', 'Devoutly religious; making or constituting a hypocritical display of virtue.', 'His pious declarations about honesty rang hollow given his well-documented record of deceit.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/pious001.mp3'),
('placate', 'To make someone less angry or hostile; to appease.', 'The company issued a public apology in an attempt to placate outraged customers.', 'https://api.dictionaryapi.dev/media/pronunciations/en/placate-au.mp3'),
('platitude', 'A remark or statement that is used too often to be interesting or thoughtful; a cliché.', 'The graduation speech was a string of platitudes that left the students unmoved.', 'https://api.dictionaryapi.dev/media/pronunciations/en/platitude-au.mp3'),
('pragmatic', 'Dealing with things sensibly and realistically; practical rather than idealistic.', 'A pragmatic approach to the budget crisis meant making unpopular cuts immediately.', 'https://api.dictionaryapi.dev/media/pronunciations/en/pragmatic-us.mp3'),
('polemical', 'Of or involving strongly critical or controversial writing or speech; disputatious.', 'The essay was deliberately polemical, designed to provoke debate rather than resolve it.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/polemi03.mp3'),
('precipitous', 'Dangerously high or steep; done suddenly and without careful consideration.', 'The stock suffered a precipitous drop after the earnings report disappointed analysts.', 'https://api.dictionaryapi.dev/media/pronunciations/en/precipitous-us.mp3'),
('precocious', 'Having developed certain abilities or proclivities at an earlier age than usual.', 'The precocious child was reading novels at the age of five and solving algebra by seven.', 'https://api.dictionaryapi.dev/media/pronunciations/en/precocious-uk.mp3'),
('predilection', 'A preference or special liking for something; a bias in favor of something.', 'She had a predilection for brutalist architecture that most of her colleagues found baffling.', 'https://api.dictionaryapi.dev/media/pronunciations/en/predilection-uk.mp3'),
('prevaricate', 'To speak or act in an evasive way; to avoid stating the truth directly.', 'When asked directly about the finances, the CFO began to prevaricate and the board grew suspicious.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/prevar01.mp3'),
('probity', 'The quality of having strong moral principles; complete honesty and integrity.', 'Her reputation for probity made her the obvious choice to lead the ethics committee.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/probit02.mp3'),
('propitious', 'Giving or indicating a good chance of success; favorable.', 'The calm seas and clear skies seemed propitious for the start of the voyage.', 'https://api.dictionaryapi.dev/media/pronunciations/en/propitious-us.mp3'),
('prodigal', 'Spending money or resources freely and recklessly; wastefully extravagant.', 'His prodigal spending habits had exhausted his inheritance within five years.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/prodig01.mp3'),
('prosaic', 'Having the style or diction of prose; lacking poetic beauty; commonplace.', 'After years of travel writing, she found life in the suburbs unbearably prosaic.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/prosai01.mp3'),
('puerile', 'Childishly silly and immature.', 'The debate descended into puerile name-calling that embarrassed both parties.', 'https://api.dictionaryapi.dev/media/pronunciations/en/puerile-au.mp3'),
('pusillanimous', 'Showing a lack of courage or determination; timid.', 'The pusillanimous response of the international community allowed the crisis to worsen.', 'https://api.dictionaryapi.dev/media/pronunciations/en/pusillanimous-us.mp3'),
('pugnacious', 'Eager or quick to argue, quarrel, or fight; combative.', 'The pugnacious attorney was known for turning every deposition into an all-out battle.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/p/pugnac01.mp3'),
('recondite', 'Not known by many people; abstruse.', 'The dissertation explored a recondite corner of Byzantine legal history that had been largely ignored.', 'https://api.dictionaryapi.dev/media/pronunciations/en/recondite-uk.mp3'),
('recalcitrant', 'Having an obstinately uncooperative attitude toward authority; stubbornly resistant.', 'The recalcitrant student refused to comply with any of the new classroom rules.', 'https://api.dictionaryapi.dev/media/pronunciations/en/recalcitrant-au.mp3'),
('quixotic', 'Exceedingly idealistic; unrealistic and impractical.', 'His quixotic plan to cycle across every continent on a single-speed bike charmed everyone he told.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/q/quixot05.mp3'),
('refractory', 'Stubborn or unmanageable; resistant to a process or stimulus.', 'The refractory patient refused all treatment and insisted on leaving the hospital.', 'https://api.dictionaryapi.dev/media/pronunciations/en/refractory-au.mp3'),
('repudiate', 'To refuse to accept or be associated with; to deny the truth or validity of.', 'The candidate repudiated the endorsement from the extremist group within hours of it being announced.', 'https://api.dictionaryapi.dev/media/pronunciations/en/repudiate-au.mp3'),
('redolent', 'Strongly reminiscent or suggestive of something; fragrant or sweet-smelling.', 'The old library was redolent of leather bindings and decades of accumulated dust.', 'https://api.dictionaryapi.dev/media/pronunciations/en/redolent-au.mp3'),
('reticent', 'Not revealing one''s thoughts or feelings readily; reserved.', 'He was reticent about his past, deflecting personal questions with a practiced smile.', 'https://api.dictionaryapi.dev/media/pronunciations/en/reticent-au.mp3'),
('restive', 'Unable to keep still or silent; difficult to control; restless.', 'The restive crowd grew louder as the delay stretched past two hours.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/r/restiv01.mp3'),
('salient', 'Most noticeable or important; prominent.', 'The report identified three salient points that required immediate board attention.', 'https://api.dictionaryapi.dev/media/pronunciations/en/salient-au.mp3'),
('sagacious', 'Having or showing keen mental discernment and good judgment; shrewd.', 'The sagacious investor had seen the market downturn coming months before it hit.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/s/sagaci01.mp3'),
('sanguine', 'Optimistic or positive, especially in a difficult situation; blood-red.', 'Despite the setbacks, she remained sanguine about the team''s chances in the second half.', 'https://api.dictionaryapi.dev/media/pronunciations/en/sanguine-us.mp3'),
('sedulous', 'Showing dedication and diligence; persevering.', 'The sedulous researcher spent twelve years compiling the definitive history of the movement.', 'https://api.dictionaryapi.dev/media/pronunciations/en/sedulous-uk.mp3'),
('solipsistic', 'Of or characterized by the view that the self is all that exists or can be known; self-absorbed.', 'The novel''s solipsistic narrator made it difficult for readers to connect with anyone else in the story.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/s/solips03.mp3'),
('sardonic', 'Grimly mocking or cynical; disdainfully humorous.', 'His sardonic commentary on corporate culture made his podcast appointment listening for disaffected employees.', 'https://api.dictionaryapi.dev/media/pronunciations/en/sardonic-au.mp3'),
('specious', 'Superficially plausible but actually wrong; misleading in appearance.', 'The argument sounded convincing at first but closer examination revealed it to be specious.', 'https://api.dictionaryapi.dev/media/pronunciations/en/specious-us.mp3'),
('sanctimonious', 'Making a show of being morally superior to other people; self-righteous.', 'His sanctimonious lecture about healthy eating came moments before he ordered dessert.', 'https://api.dictionaryapi.dev/media/pronunciations/en/sanctimonious-au.mp3'),
('soporific', 'Tending to induce drowsiness or sleep; tediously slow or dull.', 'The professor''s soporific delivery made even the most fascinating material hard to follow.', 'https://api.dictionaryapi.dev/media/pronunciations/en/soporific-uk.mp3'),
('spurious', 'Not being what it purports to be; false or fake.', 'The document was later found to be spurious, forged sometime in the nineteenth century.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/s/spurio01.mp3'),
('stolid', 'Calm, dependable, and showing little emotion or animation.', 'The stolid bodyguard stood motionless for hours without any sign of boredom or fatigue.', 'https://api.dictionaryapi.dev/media/pronunciations/en/stolid-uk.mp3'),
('strident', 'Loud and harsh; presenting a point of view in an excessively forceful way.', 'Her strident calls for reform alienated potential allies who agreed with her on the substance.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/s/stride08.mp3'),
('subversive', 'Seeking or intended to undermine an established system or institution.', 'The novel was banned for being subversive, though later generations would call it prescient.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/s/subver01.mp3'),
('sycophant', 'A person who acts obsequiously toward someone important in order to gain advantage.', 'He surrounded himself with sycophants who never challenged his decisions, however poor.', 'https://api.dictionaryapi.dev/media/pronunciations/en/sycophant-us.mp3'),
('tangential', 'Diverging from a previous course; only slightly connected to a subject.', 'His tangential remarks about his childhood derailed what had been a productive meeting.', 'https://api.dictionaryapi.dev/media/pronunciations/en/tangential-au.mp3'),
('taciturn', 'Reserved or uncommunicative in speech; saying little.', 'The taciturn detective let his partner do all the talking during interviews.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/t/tacitu01.mp3'),
('temerity', 'Excessive confidence or boldness; audacity.', 'She had the temerity to challenge the founding partner''s strategy in front of the entire firm.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/t/temeri01.mp3'),
('tendentious', 'Promoting a particular cause or point of view; partisan.', 'The documentary was criticized for its tendentious framing of the historical events.', 'https://api.dictionaryapi.dev/media/pronunciations/en/tendentious-uk.mp3'),
('timorous', 'Showing or suffering from nervousness or a lack of confidence; timid.', 'The timorous applicant could barely make eye contact during the interview.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/t/timoro01.mp3'),
('transient', 'Lasting only for a short time; temporary.', 'The joy of a promotion is often transient, quickly giving way to the pressures of new responsibility.', 'https://api.dictionaryapi.dev/media/pronunciations/en/transient-us.mp3'),
('truculent', 'Eager or quick to argue or fight; aggressively defiant.', 'The truculent witness clashed with the prosecutor at nearly every exchange.', 'https://api.dictionaryapi.dev/media/pronunciations/en/truculent-us.mp3'),
('torpid', 'Mentally or physically inactive; lethargic.', 'The torpid economy had shown no meaningful growth for three consecutive quarters.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/t/torpid01.mp3'),
('tractable', 'Easy to deal with or control; docile.', 'Unlike its predecessor, the new software was far more tractable and user-friendly.', 'https://api.dictionaryapi.dev/media/pronunciations/en/tractable-au.mp3'),
('turgid', 'Swollen and distended; pompous or bombastic in language or style.', 'The turgid prose made what should have been a gripping story nearly unreadable.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/t/turgid01.mp3'),
('umbrage', 'Offense or annoyance; a feeling of being slighted.', 'He took umbrage at the suggestion that his motives were anything less than honorable.', 'https://api.dictionaryapi.dev/media/pronunciations/en/umbrage-us.mp3'),
('ubiquitous', 'Present, appearing, or found everywhere.', 'Smartphones have become so ubiquitous that it is now unusual to see someone without one.', 'https://api.dictionaryapi.dev/media/pronunciations/en/ubiquitous-au.mp3'),
('unctuous', 'Excessively flattering or ingratiating; oily.', 'The unctuous salesman made everyone in the room uncomfortable with his incessant compliments.', 'https://api.dictionaryapi.dev/media/pronunciations/en/unctuous-uk.mp3'),
('vacuous', 'Having or showing a lack of thought or intelligence; empty.', 'The vacuous celebrity interview added nothing of value to public discourse.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/v/vacuou01.mp3'),
('vapid', 'Offering nothing that is stimulating or challenging; insipid.', 'The vapid reality show was inexplicably popular despite having no discernible content.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/v/vapid002.mp3'),
('venal', 'Showing or motivated by susceptibility to bribery; corrupt.', 'The venal official had been taking kickbacks for years before the investigation began.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/v/venal001.mp3'),
('venerate', 'To regard with great respect; to revere.', 'The community venerated the elder for her decades of quiet service and wisdom.', 'https://api.dictionaryapi.dev/media/pronunciations/en/venerate-au.mp3'),
('verbose', 'Using or expressed in more words than are needed; wordy.', 'The verbose contract ran to ninety pages when twenty would have sufficed.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/v/verbos01.mp3'),
('vicarious', 'Experienced in the imagination through the feelings or actions of another person.', 'She lived vicariously through her well-traveled friends, poring over their photographs.', 'https://api.dictionaryapi.dev/media/pronunciations/en/vicarious-au.mp3'),
('vindictive', 'Having or showing a strong or unreasoning desire for revenge.', 'The vindictive review seemed motivated more by personal grievance than honest criticism.', 'https://api.dictionaryapi.dev/media/pronunciations/en/vindictive-au.mp3'),
('vitriolic', 'Filled with bitter criticism or malice; caustic.', 'The vitriolic response to her article shocked even those who disagreed with her position.', 'https://api.dictionaryapi.dev/media/pronunciations/en/vitriolic-au.mp3'),
('vociferous', 'Expressing or characterized by vehement opinions; loud and forceful.', 'Vociferous protests outside the courthouse drew significant media attention.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/v/vocife05.mp3'),
('voluble', 'Speaking or spoken incessantly and fluently; glib.', 'The voluble tour guide had a story for every building, street, and lamppost in the city.', 'https://media.merriam-webster.com/audio/prons/en/us/mp3/v/volubl01.mp3'),
('wanton', 'Deliberate and unprovoked; having no justification; licentious.', 'The wanton destruction of the archive was condemned as an act of cultural vandalism.', 'https://api.dictionaryapi.dev/media/pronunciations/en/wanton-au.mp3'),
('zenith', 'The time at which something is most powerful or successful; the highest point.', 'The artist reached the zenith of her career with her third album, which sold ten million copies.', 'https://api.dictionaryapi.dev/media/pronunciations/en/zenith-au.mp3'),
('zealous', 'Having or showing zeal; fervent and enthusiastic.', 'The zealous intern worked sixteen-hour days trying to impress the partners.', 'https://api.dictionaryapi.dev/media/pronunciations/en/zealous-au.mp3');